import{_ as t,o as d,c as a,a2 as o}from"./chunks/framework.Cd7mb1YL.js";const w=JSON.parse('{"title":"MawyViewer","description":"A Markdown document, rendered and not editable. See the viewer for what it does and why.","frontmatter":{"title":"MawyViewer","order":1},"headers":[],"relativePath":"api/components/mawy-viewer.md","filePath":"en/api/components/mawy-viewer.md","lastUpdated":1789277504000}'),r={name:"api/components/mawy-viewer.md"};function i(c,e,s,n,h,l){return d(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="mawyviewer" tabindex="-1"><code>MawyViewer</code> <a class="header-anchor" href="#mawyviewer" aria-label="Permalink to &quot;\`MawyViewer\`&quot;">​</a></h1><p>A Markdown document, rendered and not editable. See <a href="./../../guide/viewer">the viewer</a> for what it does and why.</p><div class="mawy-fw" data-fw="react"><div class="language-tsx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">tsx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { MawyViewer } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;mawy-react&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">MawyViewer</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> value</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{document} /&gt;;</span></span></code></pre></div><p>Every prop of <code>&lt;div&gt;</code> is accepted and forwarded, apart from <code>children</code> and <code>onChange</code>. A <code>ref</code> reaches the outermost element.</p></div><div class="mawy-fw" data-fw="flutter"><div class="language-dart vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dart</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;package:mawy/mawy.dart&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">MawyViewer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(value</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> document);</span></span></code></pre></div><p>Built on <code>package:flutter/widgets.dart</code> alone, with no Material and no Cupertino, so it sits inside a <code>MaterialApp</code>, a <code>CupertinoApp</code> or a bare <code>WidgetsApp</code> without pulling in a second design system.</p></div><h2 id="the-document" tabindex="-1">The document <a class="header-anchor" href="#the-document" aria-label="Permalink to &quot;The document&quot;">​</a></h2><div class="mawy-fw" data-fw="react"><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>string</code></td><td>—</td><td>The document, as Markdown. Passing it makes the document the application&#39;s: it will not change on its own.</td></tr><tr><td><code>defaultValue</code></td><td><code>string</code></td><td><code>&#39;&#39;</code></td><td>The document to start with, when the viewer is to keep it itself.</td></tr><tr><td><code>onValueChange</code></td><td><code>(value: string, file: File | null) =&gt; void</code></td><td>—</td><td>A new document, and the file it came from. Called whether or not <code>value</code> is being passed.</td></tr><tr><td><code>empty</code></td><td><code>ReactNode</code></td><td>the file picker</td><td>What to draw instead when there is no document.</td></tr></tbody></table><p>With neither <code>value</code> nor <code>defaultValue</code>, the viewer becomes the file picker. That is part of the component&#39;s design, not a fallback.</p></div><div class="mawy-fw" data-fw="flutter"><table tabindex="0"><thead><tr><th>Argument</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>String</code></td><td>required</td><td>The document, as Markdown.</td></tr></tbody></table><p><code>value</code> is required here where the React package makes it optional, because that is where a file picker would have gone. Picking a file needs a plugin, which this package does not include and an application usually already has, so the application opens the file and Mawy draws it.</p></div><h2 id="reading-and-drawing" tabindex="-1">Reading and drawing <a class="header-anchor" href="#reading-and-drawing" aria-label="Permalink to &quot;Reading and drawing&quot;">​</a></h2><div class="mawy-fw" data-fw="react"><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>parse</code></td><td><a href="./../types/parse-options"><code>MawyParseOptions</code></a></td><td><code>{ gfm: true, breaks: false, definitionLists: true }</code></td><td>How the Markdown is read.</td></tr><tr><td><code>html</code></td><td><a href="./../types/html-policy"><code>MawyHtmlPolicy</code></a></td><td><code>&#39;escape&#39;</code></td><td>What becomes of raw HTML written inside the document.</td></tr><tr><td><code>linkTarget</code></td><td><a href="./../types/link-target"><code>MawyLinkTarget</code></a></td><td><code>&#39;blank&#39;</code></td><td>Where a link the document wrote opens.</td></tr><tr><td><code>linkRel</code></td><td><a href="./../types/link-target#mawylinkrel"><code>MawyLinkRel</code></a></td><td>—</td><td>What such a link declares about where it goes. Added to what it already declares.</td></tr><tr><td><code>links</code></td><td><a href="./../types/drawing-policy#mawylinkpolicy"><code>MawyLinkPolicy</code></a></td><td><code>&#39;show&#39;</code></td><td>How a link the document wrote is drawn: as a link, as its words, as its source, or not at all.</td></tr><tr><td><code>images</code></td><td><a href="./../types/drawing-policy#mawyimagepolicy"><code>MawyImagePolicy</code></a></td><td><code>&#39;show&#39;</code></td><td>How a picture is drawn: fetched, as its description, as its source, or not at all.</td></tr><tr><td><code>locale</code></td><td><a href="./../types/locale"><code>MawyLocale</code></a></td><td><code>&#39;en&#39;</code></td><td>The language of the viewer&#39;s own interface. Nothing to do with the document.</td></tr><tr><td><code>strings</code></td><td><code>Partial&lt;</code><a href="./../types/locale#mawystrings"><code>MawyStrings</code></a><code>&gt;</code></td><td>—</td><td>The interface&#39;s words, some or all of them, over the ones <code>locale</code> has.</td></tr><tr><td><code>highlight</code></td><td><a href="./../types/highlighter"><code>MawyHighlight</code></a></td><td>—</td><td>What colours a fenced code block. Nothing by default.</td></tr><tr><td><code>directives</code></td><td><a href="./../types/directives"><code>MawyDirectives</code></a></td><td>—</td><td>What draws the constructs this package does not know about.</td></tr><tr><td><code>image</code></td><td><code>ComponentType&lt;</code><a href="./../types/image"><code>MawyImageProps</code></a><code>&gt;</code></td><td>an <code>&lt;img&gt;</code></td><td>What draws a picture the document points at.</td></tr><tr><td><code>resolveUrl</code></td><td><a href="./../types/url-resolver"><code>MawyUrlResolver</code></a></td><td>—</td><td>Where a relative URL in the document points.</td></tr><tr><td><code>anchorPrefix</code></td><td><code>string</code></td><td>—</td><td>Put in front of every anchor this viewer gives a heading or a footnote, so two viewers on one page stop colliding.</td></tr><tr><td><code>headingBase</code></td><td><code>number</code></td><td><code>1</code></td><td>Which of <code>h1</code> to <code>h6</code> the document&#39;s own <code>#</code> is drawn as.</td></tr></tbody></table></div><div class="mawy-fw" data-fw="flutter"><table tabindex="0"><thead><tr><th>Argument</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>parse</code></td><td><a href="./../types/parse-options"><code>MawyParseOptions</code></a></td><td><code>MawyParseOptions()</code></td><td>How the Markdown is read.</td></tr><tr><td><code>locale</code></td><td><a href="./../types/locale"><code>MawyLocale</code></a></td><td><code>MawyLocale.en</code></td><td>The language of the viewer&#39;s own interface. Nothing to do with the document.</td></tr><tr><td><code>strings</code></td><td><a href="./../types/locale#mawystrings"><code>MawyStrings?</code></a></td><td>—</td><td>The interface&#39;s words, where the application has its own. Given, <code>locale</code> says nothing.</td></tr><tr><td><code>onLinkTap</code></td><td><code>void Function(String url, String? title)?</code></td><td>—</td><td>What a tapped link does.</td></tr><tr><td><code>links</code></td><td><a href="./../types/drawing-policy#mawylinkpolicy"><code>MawyLinkPolicy</code></a></td><td><code>MawyLinkPolicy.show</code></td><td>How a link the document wrote is drawn: as a link, as its words, as its source, or not at all.</td></tr><tr><td><code>images</code></td><td><a href="./../types/drawing-policy#mawyimagepolicy"><code>MawyImagePolicy</code></a></td><td><code>MawyImagePolicy.show</code></td><td>How a picture is drawn: fetched, as its description, as its source, or not at all.</td></tr><tr><td><code>highlight</code></td><td><a href="./../types/highlighter"><code>MawyHighlighter?</code></a></td><td>—</td><td>What colours a fenced code block. Nothing by default.</td></tr><tr><td><code>directives</code></td><td><code>Map&lt;String, </code><a href="./../types/directives"><code>MawyDirectiveBuilder</code></a><code>&gt;?</code></td><td>—</td><td>What draws the constructs this package does not know about.</td></tr><tr><td><code>imageBuilder</code></td><td><a href="./../types/image"><code>MawyImageBuilder?</code></a></td><td>the viewer draws it</td><td>What draws a picture the document points at.</td></tr><tr><td><code>resolveUrl</code></td><td><a href="./../types/url-resolver"><code>MawyUrlResolver?</code></a></td><td>—</td><td>Where a relative URL in the document points.</td></tr></tbody></table><p>There is no <code>linkTarget</code> either. What opening a link means is <code>onLinkTap</code>&#39;s whole subject here, and where it opens is part of what an application answers with.</p><p>There is no <code>html</code> argument, and there will not be one: raw HTML written inside a document is shown as the characters it was written with, because there is no HTML here to draw it as.</p><p><code>onLinkTap</code> is unset by default, and a link does nothing until it is given. Opening a URL means handing it to the platform, and which URLs an application is willing to hand over is not a viewer&#39;s decision. The scheme allowlist has already run by the time it is called, so a <code>javascript:</code> URL never reaches it. The rest is the application&#39;s to decide.</p></div><h2 id="appearance" tabindex="-1">Appearance <a class="header-anchor" href="#appearance" aria-label="Permalink to &quot;Appearance&quot;">​</a></h2><div class="mawy-fw" data-fw="react"><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>colorScheme</code></td><td><a href="./../types/color-scheme"><code>MawyColorScheme</code></a></td><td>—</td><td>The palette, when the application owns it.</td></tr><tr><td><code>defaultColorScheme</code></td><td><code>MawyColorScheme</code></td><td><code>&#39;system&#39;</code></td><td>The palette to start with.</td></tr><tr><td><code>onColorSchemeChange</code></td><td><code>(scheme: MawyColorScheme) =&gt; void</code></td><td>—</td><td>Called whenever it changes, controlled or not.</td></tr><tr><td><code>typography</code></td><td><code>Partial&lt;</code><a href="./../types/typography"><code>MawyTypography</code></a><code>&gt;</code></td><td>—</td><td>How the document is set, when the application owns it.</td></tr><tr><td><code>defaultTypography</code></td><td><code>Partial&lt;MawyTypography&gt;</code></td><td>see below</td><td>What it is set as to begin with.</td></tr><tr><td><code>onTypographyChange</code></td><td><code>(typography: MawyTypography) =&gt; void</code></td><td>—</td><td>Called whenever it changes, controlled or not.</td></tr><tr><td><code>toolbar</code></td><td><a href="./../types/viewer-toolbar-item"><code>MawyViewerToolbarOption</code></a></td><td><code>true</code></td><td>Which controls the toolbar has, and in what order.</td></tr><tr><td><code>frame</code></td><td><a href="./../types/frame"><code>MawyFrame</code></a></td><td><code>&#39;box&#39;</code></td><td>Whether the viewer has a frame around it, or floats in the page.</td></tr><tr><td><code>toolbarPlacement</code></td><td><a href="./../types/frame#mawytoolbarplacement"><code>MawyToolbarPlacement</code></a></td><td><code>&#39;top&#39;</code></td><td>Which end the toolbar and the find bar are at.</td></tr><tr><td><code>fonts</code></td><td><code>readonly </code><a href="./../types/font"><code>MawyFont</code></a><code>[]</code></td><td><code>MAWY_SYSTEM_FONTS</code></td><td>The typefaces the toolbar offers, in the order it lists them.</td></tr></tbody></table><p>Anything left out of <code>typography</code> or <code>defaultTypography</code> keeps its default, so <code>{ fontSize: 18 }</code> is a whole answer. The defaults are <code>sans</code>, 16px, a line height of 1.7, no extra letter spacing and the <code>normal</code> measure.</p></div><div class="mawy-fw" data-fw="flutter"><table tabindex="0"><thead><tr><th>Argument</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>colorScheme</code></td><td><a href="./../types/color-scheme"><code>MawyColorScheme</code></a></td><td><code>MawyColorScheme.system</code></td><td>The palette. <code>system</code> follows the platform.</td></tr><tr><td><code>onColorSchemeChange</code></td><td><code>ValueChanged&lt;MawyColorScheme&gt;?</code></td><td>—</td><td>Called when the reader changes it from the toolbar.</td></tr><tr><td><code>tokens</code></td><td><a href="./../theming"><code>MawyTokensBuilder?</code></a></td><td>the stylesheet&#39;s own</td><td>The colours to draw in, given the brightness the viewer settled on.</td></tr><tr><td><code>typography</code></td><td><a href="./../types/typography"><code>MawyTypography?</code></a></td><td>—</td><td>How the document is set, when the application owns it.</td></tr><tr><td><code>defaultTypography</code></td><td><code>MawyTypography</code></td><td><code>MawyTypography()</code></td><td>How it is set to begin with, when the viewer keeps it itself.</td></tr><tr><td><code>onTypographyChange</code></td><td><code>ValueChanged&lt;MawyTypography&gt;?</code></td><td>—</td><td>Called whether or not <code>typography</code> is being passed.</td></tr><tr><td><code>toolbar</code></td><td><code>List&lt;</code><a href="./../types/viewer-toolbar-item"><code>MawyViewerToolbarItem</code></a><code>&gt;</code></td><td><code>kMawyViewerToolbar</code></td><td>The controls to draw and the order to draw them in. <code>const []</code> for none.</td></tr><tr><td><code>frame</code></td><td><a href="./../types/frame"><code>MawyFrame</code></a></td><td><code>MawyFrame.box</code></td><td>Whether the viewer has a frame around it, or floats on the screen.</td></tr><tr><td><code>toolbarPlacement</code></td><td><a href="./../types/frame#mawytoolbarplacement"><code>MawyToolbarPlacement</code></a></td><td><code>MawyToolbarPlacement.top</code></td><td>Which end the toolbar and the find bar are at.</td></tr></tbody></table><p>The colour scheme is one argument rather than the controlled pair the typography uses. Hand the viewer a <code>light</code> or a <code>dark</code> and it stays there; leave it at <code>system</code> and it follows the platform. <code>onColorSchemeChange</code> reports what the reader picked from the toolbar, so an application that wants to remember the choice passes the remembered value back in.</p><p><code>MawyTypography</code> is a class with a default for every field rather than a bag of optional ones, so <code>MawyTypography(fontSize: 18)</code> is a whole answer and <code>copyWith</code> changes one thing about an existing one. The defaults are <code>sans</code>, 16 logical pixels, a line height of 1.7, no extra letter spacing and the <code>normal</code> measure.</p><p>There is no <code>fonts</code> argument. The package ships no typefaces and names none, so a face an application has bundled is named through <a href="./../types/typography"><code>MawyTypography.fontFamilyName</code></a> rather than offered from a list.</p></div><h2 id="opening-files" tabindex="-1">Opening files <a class="header-anchor" href="#opening-files" aria-label="Permalink to &quot;Opening files&quot;">​</a></h2><div class="mawy-fw" data-fw="react"><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>fileDrop</code></td><td><code>boolean</code></td><td><code>true</code>, unless <code>value</code> is passed</td><td>Whether a file dropped on the viewer opens in it.</td></tr><tr><td><code>accept</code></td><td><code>string</code></td><td>every Markdown and text extension</td><td>What the file picker offers.</td></tr></tbody></table><p>A file larger than five megabytes is refused rather than read.</p></div><div class="mawy-fw" data-fw="flutter"><p>Nothing here: this package does not open files, and <code>value</code> above says why.</p></div><h2 id="layout-and-scrolling" tabindex="-1">Layout and scrolling <a class="header-anchor" href="#layout-and-scrolling" aria-label="Permalink to &quot;Layout and scrolling&quot;">​</a></h2><div class="mawy-fw" data-fw="flutter"><table tabindex="0"><thead><tr><th>Argument</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>padding</code></td><td><code>EdgeInsetsGeometry?</code></td><td>the React package&#39;s own numbers</td><td>The space around the document.</td></tr><tr><td><code>scrollController</code></td><td><code>ScrollController?</code></td><td>one of its own</td><td>The document&#39;s scroller, so an application can drive it or watch it.</td></tr><tr><td><code>anchors</code></td><td><a href="./../types/viewer-anchors"><code>MawyViewerAnchors?</code></a></td><td>—</td><td>Where each top-level block of the document ends up, filled in as it draws — for anything lining a second view up with this one.</td></tr></tbody></table></div><div class="mawy-fw" data-fw="react"><p>Padding and scrolling belong to the page rather than the component, because the viewer is an element in a document that already has both. The numbers it draws with are <code>--mawy-*</code> custom properties, which <a href="./../theming">theming</a> lists.</p></div>`,19)])])}const y=t(r,[["render",i]]);export{w as __pageData,y as default};
